// Prepare file data for Azure OCR
// Azure expects binary data in request body, not JSON with base64
const items = $input.all();
const result = [];

for (const item of items) {
  // DEBUG: Log what we received
  console.log('=== DEBUG: Prepare File Data Node ===');
  console.log('Item JSON keys:', Object.keys(item.json || {}));
  console.log('Item JSON sample:', JSON.stringify(item.json, null, 2).substring(0, 500));
  console.log('Has binary property:', !!item.binary);

  const body = item.json.body || item.json;

  let fileName = 'document';
  let fileType = 'pdf';
  let contentType = 'application/pdf';
  let binaryData = null;

  // When webhook has rawBody: true, n8n stores raw binary data in item.binary
  // Check all possible binary property names from webhook
  const binaryKeys = Object.keys(item.binary || {});
  console.log('Binary keys found:', binaryKeys);

  if (item.binary) {
    for (const key of binaryKeys) {
      console.log(`Binary[${key}] type:`, typeof item.binary[key]);
      console.log(`Binary[${key}] has data property:`, !!item.binary[key]?.data);
      if (item.binary[key]?.data) {
        console.log(`Binary[${key}].data type:`, typeof item.binary[key].data);
        console.log(`Binary[${key}].data length:`, item.binary[key].data?.length || 'N/A');
        console.log(`Binary[${key}].mimeType:`, item.binary[key].mimeType);
        console.log(`Binary[${key}].fileName:`, item.binary[key].fileName);
      }
    }
  }

  // Try to find binary data - check common property names
  let binaryKey = null;
  let foundBinary = null;

  if (binaryKeys.length > 0) {
    // Check for 'data' first (most common for rawBody webhooks)
    if (item.binary.data && item.binary.data.data) {
      binaryKey = 'data';
      foundBinary = item.binary.data;
    } else if (item.binary.data && Buffer.isBuffer(item.binary.data)) {
      // Handle case where data is a Buffer directly
      binaryKey = 'data';
      foundBinary = {
        data: item.binary.data.toString('base64'),
        mimeType: item.binary.data.mimeType || 'application/pdf',
        fileName: item.binary.data.fileName || 'document'
      };
    } else {
      // Check other keys
      binaryKey = binaryKeys.find(key => item.binary[key] && item.binary[key].data);
      if (binaryKey) {
        foundBinary = item.binary[binaryKey];
      }
    }
  }

  // Handle file read from disk or binary file upload (already in binary format)
  if (foundBinary && foundBinary.data) {
    // Binary file from Read Binary Files node, manual trigger, or webhook with rawBody
    binaryData = foundBinary;

    // Extract metadata from headers if available (webhook case)
    const headers = item.json.headers || {};
    const contentDisposition = headers['content-disposition'] || headers['Content-Disposition'] || '';
    const contentTypeHeader = headers['content-type'] || headers['Content-Type'] || '';

    // Extract filename from Content-Disposition header if present
    if (contentDisposition) {
      const filenameMatch = contentDisposition.match(/filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/);
      if (filenameMatch && filenameMatch[1]) {
        fileName = filenameMatch[1].replace(/['"]/g, '');
      }
    }

    // Get content type from header if available
    if (contentTypeHeader) {
      contentType = contentTypeHeader.split(';')[0].trim();
    } else if (binaryData.mimeType) {
      contentType = binaryData.mimeType;
    }

    // Get filename from binary data if not found in headers
    if (!fileName || fileName === 'document') {
      fileName = binaryData.fileName || item.json.fileName || item.json.filePath?.split('/').pop() || 'document';
    }

    // Determine file type from content type or filename
    const lowerFileName = fileName.toLowerCase();
    if (contentType.includes('pdf') || lowerFileName.endsWith('.pdf')) {
      fileType = 'pdf';
      contentType = 'application/pdf';
    } else if (contentType.includes('image') || lowerFileName.match(/\.(jpg|jpeg|png|gif|bmp|tiff|webp)$/i)) {
      fileType = 'image';
      if (!contentType || contentType === 'application/pdf') {
        if (lowerFileName.endsWith('.png')) {
          contentType = 'image/png';
        } else if (lowerFileName.match(/\.(jpg|jpeg)$/i)) {
          contentType = 'image/jpeg';
        } else if (lowerFileName.endsWith('.gif')) {
          contentType = 'image/gif';
        } else if (lowerFileName.match(/\.(bmp|tiff|webp)$/i)) {
          contentType = 'image/' + lowerFileName.split('.').pop();
        } else {
          contentType = contentType || 'image/jpeg';
        }
      }
    }

    // Ensure binaryData has proper format (data must be base64 string)
    // If data is already a base64 string, use it; if it's a Buffer, convert it
    let base64Data = binaryData.data;
    if (Buffer.isBuffer(base64Data)) {
      base64Data = base64Data.toString('base64');
    } else if (typeof base64Data !== 'string') {
      // Try to convert to string if it's not already
      base64Data = String(base64Data);
    }

    // Ensure binaryData has proper mimeType and data format
    binaryData = {
      data: base64Data,
      mimeType: binaryData.mimeType || contentType,
      fileName: binaryData.fileName || fileName
    };
  }
  // Handle webhook that converted binary to base64 (n8n webhook behavior)
  else if (item.json.base64Source) {
    // Webhook received binary and converted to base64
    // Validate and use the base64 string directly
    let base64String = item.json.base64Source;

    // Remove any data URL prefix if present
    if (base64String.includes(',')) {
      base64String = base64String.split(',')[1];
    }

    // Determine content type from headers
    const headers = item.json.headers || {};
    const contentTypeHeader = headers['content-type'] || headers['Content-Type'] || 'application/pdf';
    contentType = contentTypeHeader.split(';')[0].trim();
    fileType = contentType.includes('pdf') ? 'pdf' : 'image';

    // Create binary data object in n8n format
    // The 'data' field must contain the base64 string (not decoded)
    // HTTP Request node will automatically decode it when sending
    binaryData = {
      data: base64String,
      mimeType: contentType,
      fileName: item.json.fileName || 'document.pdf'
    };

    fileName = item.json.fileName || 'document.pdf';
  }
  // Handle webhook JSON payload with base64 file data
  else if (body && body.file) {
    // Base64 string - keep as base64 for binary property
    const base64String = body.file;
    binaryData = {
      data: base64String,
      mimeType: contentType,
      fileName: body.original_filename || body.filename || 'document'
    };
    fileName = body.original_filename || body.filename || 'document';
    fileType = body.file_type || 'pdf';
    contentType = fileType === 'pdf' ? 'application/pdf' : (body.content_type || 'image/jpeg');
  }
  // Handle webhook with binary data field (legacy format)
  else if (body && body.data) {
    // Binary data - convert to base64
    binaryData = {
      data: Buffer.from(body.data, 'binary').toString('base64'),
      mimeType: contentType,
      fileName: body.filename || 'document'
    };
    fileName = body.filename || 'document';
    fileType = body.file_type || 'pdf';
    contentType = fileType === 'pdf' ? 'application/pdf' : (body.content_type || 'image/jpeg');
  }

  if (!binaryData) {
    // Debug: log what we received
    console.log('ERROR: No binary data found!');
    console.log('Item JSON:', JSON.stringify(item.json, null, 2));
    console.log('Binary keys:', binaryKeys);
    console.log('Has binary:', !!item.binary);
    if (item.binary) {
      console.log('Binary object:', JSON.stringify(Object.keys(item.binary), null, 2));
    }
    throw new Error('No file data found. Please upload a file via manual trigger, read from disk, or send file data via webhook. Make sure to send raw binary data with Content-Type header when using webhook with rawBody option.');
  }

  // DEBUG: Log what we're outputting
  console.log('SUCCESS: Binary data prepared');
  console.log('File name:', fileName);
  console.log('File type:', fileType);
  console.log('Content type:', contentType);
  console.log('Binary data type:', typeof binaryData.data);
  console.log('Binary data length (base64):', binaryData.data?.length || 'N/A');

  // Calculate actual binary size
  if (binaryData.data && typeof binaryData.data === 'string') {
    try {
      const buffer = Buffer.from(binaryData.data, 'base64');
      console.log('Binary data size (decoded bytes):', buffer.length);
      console.log('Binary data first 20 bytes (hex):', buffer.slice(0, 20).toString('hex'));

      // Validate PDF signature if it's supposed to be a PDF
      if (contentType.includes('pdf') || fileType === 'pdf') {
        const pdfSignature = buffer.slice(0, 4).toString();
        console.log('PDF signature check:', pdfSignature, pdfSignature === '%PDF' ? '✓ Valid PDF' : '✗ Invalid PDF signature');
        if (pdfSignature !== '%PDF' && buffer.length > 4) {
          console.warn('WARNING: File does not have valid PDF signature!');
        }
      }
    } catch (e) {
      console.error('Error decoding base64:', e.message);
    }
  }

  console.log('Binary mimeType:', binaryData.mimeType);
  console.log('Binary fileName:', binaryData.fileName);

  // Pass binary data and metadata to next node
  result.push({
    json: {
      fileName: fileName,
      fileType: fileType,
      contentType: contentType,
      originalData: body || item.json,
      // DEBUG: Include debug info in output
      _debug: {
        hasBinary: !!item.binary,
        binaryKeys: binaryKeys,
        binaryDataFound: !!binaryData,
        binaryDataType: typeof binaryData?.data,
        binaryDataLength: binaryData?.data?.length || 0,
        inputJsonKeys: Object.keys(item.json || {}),
        headers: item.json.headers || item.json.Headers || null
      }
    },
    binary: {
      data: binaryData
    }
  });

  console.log('=== END DEBUG ===');
}

return result;

// Extract Request ID and debug HTTP response
const items = $input.all();
const result = [];

for (const item of items) {
  // DEBUG: Log the response structure
  console.log('=== DEBUG: Extract Request ID ===');
  console.log('Item JSON keys:', Object.keys(item.json || {}));
  console.log('Full item JSON:', JSON.stringify(item.json, null, 2).substring(0, 1000));

  // HTTP Request node with fullResponse returns different structures
  // Try multiple possible structures
  let statusCode = item.json.statusCode || item.json.status || item.json.code || null;
  let headers = item.json.headers || item.json.header || {};
  let apimRequestId = null;

  // Try to extract apim-request-id from headers (case-insensitive)
  if (headers) {
    // Headers might be an object with lowercase keys
    apimRequestId = headers['apim-request-id'] || 
                   headers['Apim-Request-Id'] || 
                   headers['APIM-Request-Id'] ||
                   headers['apim-request-id']?.toLowerCase() ||
                   null;

    // If headers is an array or has different structure
    if (!apimRequestId && Array.isArray(headers)) {
      const headerObj = headers.find(h => h.name && h.name.toLowerCase() === 'apim-request-id');
      apimRequestId = headerObj?.value || null;
    }
  }

  console.log('Status code:', statusCode);
  console.log('Headers type:', typeof headers);
  console.log('Headers keys:', headers ? Object.keys(headers) : 'N/A');
  console.log('APIM Request ID:', apimRequestId);

  // Get file info from previous node
  const prepareFileDataNode = $('Prepare File Data');
  const fileName = prepareFileDataNode?.item?.json?.fileName || 'document';
  const fileType = prepareFileDataNode?.item?.json?.fileType || 'pdf';

  result.push({
    json: {
      statusCode: statusCode,
      apimRequestId: apimRequestId || '',
      fileName: fileName,
      fileType: fileType,
      status: 'submitted',
      headers: headers,
      _debug: {
        responseKeys: Object.keys(item.json || {}),
        hasStatusCode: !!statusCode,
        hasHeaders: !!headers,
        headersType: typeof headers
      }
    }
  });

  console.log('=== END DEBUG ===');
}

return result;

